#include <stdio.h>
#include <stdarg.h>

int fish_total(int count, ...) {
    va_list list;
    va_start(list, count);
    int sum = 0;
    for (int i = 0; i < count; i++) {
        sum += va_arg(list, int);
    }
    va_end(list);
    return sum;
}

int main(void) {
    printf("%d\n", fish_total(3, {a}, {b}, {c}));
    return 0;
}
